using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class FinalCaveHillsideDependencies{
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var current=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.ToLower().Contains("tree")||t.name.ToLower().Contains("trunk")).ToArray();string Key(Transform t){var id=GlobalObjectId.GetGlobalObjectIdSlow(t);return id.targetObjectId+":"+id.targetPrefabId;}var map=current.ToDictionary(Key,t=>t);File.Copy("Temp/CaveHillsideBaseline.unity","Assets/Scenes/CaveHillsideBaseline.unity",true);AssetDatabase.ImportAsset("Assets/Scenes/CaveHillsideBaseline.unity");var baseline=EditorSceneManager.OpenScene("Assets/Scenes/CaveHillsideBaseline.unity",OpenSceneMode.Additive);var changed=new List<Collider>();foreach(var t in baseline.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true))){if(map.TryGetValue(Key(t),out var live)&&Vector3.Distance(t.localPosition,live.localPosition)>.01f){var c=live.GetComponent<Collider>();if(c)changed.Add(c);}}EditorSceneManager.CloseScene(baseline,true);AssetDatabase.DeleteAsset("Assets/Scenes/CaveHillsideBaseline.unity");Physics.SyncTransforms();var fix=changed.Where(c=>Math.Abs(Racer.Editor.BackyardReverseAuthoring.Ground(c.bounds.center)-c.bounds.min.y)>.08f).ToArray();typeof(Racer.Editor.BackyardReverseAuthoring).GetMethod("Trees",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{(Func<Collider,bool>)(c=>false),(Func<Collider,bool>)(c=>fix.Contains(c))});Physics.SyncTransforms();float gap=changed.Select(c=>Math.Abs(Racer.Editor.BackyardReverseAuthoring.Ground(c.bounds.center)-c.bounds.min.y)).DefaultIfEmpty(0).Max();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var deps=AssetDatabase.GetDependencies(scene.path,true).ToHashSet();int removed=0;foreach(string path in File.ReadAllLines("Temp/cavehillside-new-trees.txt")){if(!path.EndsWith(".asset")||deps.Contains(path))continue;if(AssetDatabase.DeleteAsset(path))removed++;}File.WriteAllText("Docs/CaveHillside/final-dependencies.txt",$"Changed existing trees={changed.Count}; final reseats={fix.Length}; maximum final tree foot gap={gap:F4}m; discarded unreferenced intermediate tree meshes={removed}. Main road/props original transforms preserved. No new shrubs required.");return File.ReadAllText("Docs/CaveHillside/final-dependencies.txt");}
}
